-- Lines are regenerated by generation (no row removal): a statement shows only the lines of its current `gen`;
-- an unwanted last statement is voided — it keeps its row for the audit trail and frees its month and number.
alter table pst_statements add column if not exists gen int not null default 1;
alter table pst_statements add column if not exists voided_at timestamptz;
alter table pst_lines add column if not exists gen int not null default 1;

create or replace function pst_save(p jsonb, p_lines jsonb) returns uuid language plpgsql security definer set search_path to 'public' as $f$
declare sid uuid := nullif(p->>'id', '')::uuid; s pst_statements%rowtype; c fin_contracts%rowtype; n int; g int := 1;
begin
  select * into c from fin_contracts where id = (p->>'contract_id')::uuid;
  if c.id is null then raise exception 'contract_not_found'; end if;
  if not pst_can_write(c.master_project_id) then raise exception 'not_allowed' using errcode = '42501'; end if;
  if sid is null then
    if exists (select 1 from pst_statements where contract_id = c.id and part = p->>'part' and voided_at is null and period_key = p->>'period_key') then raise exception 'exists'; end if;
    if exists (select 1 from pst_statements where contract_id = c.id and part = p->>'part' and voided_at is null and status in ('draft','submitted','rejected')) then raise exception 'open_exists'; end if;
    if exists (select 1 from pst_statements where contract_id = c.id and part = p->>'part' and voided_at is null and period_to >= (p->>'period_from')::date) then raise exception 'not_after_last'; end if;
    select coalesce(max(no), 0) + 1 into n from pst_statements where contract_id = c.id and part = p->>'part' and voided_at is null;
    insert into pst_statements (master_project_id, contract_id, part, no, period_key, period_from, period_to)
      values (c.master_project_id, c.id, p->>'part', n, p->>'period_key', (p->>'period_from')::date, (p->>'period_to')::date) returning id into sid;
  else
    select * into s from pst_statements where id = sid;
    if s.id is null or s.voided_at is not null then raise exception 'not_found'; end if;
    if s.status not in ('draft','rejected') then raise exception 'locked'; end if;
    g := s.gen + 1;
  end if;
  insert into pst_lines (statement_id, gen, source_kind, source_id, code, title, unit, group_label, unit_price, base_qty, base_amount, sys_cum_qty, sys_cum_amount, cum_amount, prev_amount, edited, note, detail)
  select sid, g, e->>'source_kind', (e->>'source_id')::uuid, coalesce(e->>'code',''), coalesce(e->>'title',''), coalesce(e->>'unit',''), coalesce(e->>'group_label',''),
         coalesce((e->>'unit_price')::numeric,0), coalesce((e->>'base_qty')::numeric,0), coalesce((e->>'base_amount')::numeric,0),
         coalesce((e->>'sys_cum_qty')::numeric,0), coalesce((e->>'sys_cum_amount')::numeric,0), coalesce((e->>'cum_amount')::numeric,0), coalesce((e->>'prev_amount')::numeric,0),
         coalesce((e->>'edited')::boolean,false), coalesce(e->>'note',''), coalesce(e->'detail','{}'::jsonb)
    from jsonb_array_elements(p_lines) e
  on conflict (statement_id, source_kind, source_id) do update set gen = excluded.gen, code = excluded.code, title = excluded.title, unit = excluded.unit, group_label = excluded.group_label,
    unit_price = excluded.unit_price, base_qty = excluded.base_qty, base_amount = excluded.base_amount, sys_cum_qty = excluded.sys_cum_qty, sys_cum_amount = excluded.sys_cum_amount,
    cum_amount = excluded.cum_amount, prev_amount = excluded.prev_amount, edited = excluded.edited, note = excluded.note, detail = excluded.detail;
  update pst_statements set gen = g, status = 'draft', reject_reason = '', note = coalesce(p->>'note', note),
    cum_sys = coalesce((p->>'cum_sys')::numeric,0), cum_amount = coalesce((p->>'cum_amount')::numeric,0), prev_amount = coalesce((p->>'prev_amount')::numeric,0),
    this_amount = coalesce((p->>'this_amount')::numeric,0), cap = nullif(p->>'cap','')::numeric, deductions = coalesce(p->'deductions','{}'::jsonb), payable = coalesce((p->>'payable')::numeric,0)
  where id = sid;
  return sid;
end $f$;

create or replace function pst_void(p_stmt uuid) returns void language plpgsql security definer set search_path to 'public' as $f$
declare s pst_statements%rowtype;
begin
  select * into s from pst_statements where id = p_stmt;
  if s.id is null or s.voided_at is not null then return; end if;
  if not pst_can_write(s.master_project_id) then raise exception 'not_allowed' using errcode = '42501'; end if;
  if s.status in ('approved','posted') then raise exception 'locked'; end if;
  if exists (select 1 from pst_statements where contract_id = s.contract_id and part = s.part and voided_at is null and no > s.no) then raise exception 'not_last'; end if;
  update pst_statements set voided_at = now(), no = -extract(epoch from clock_timestamp())::int, period_key = s.period_key || '~' || left(s.id::text, 8) where id = p_stmt;
end $f$;
